  1→/*
  2→ * client.h - XWayland/XDG client abstraction layer
  3→ *
  4→ * Static inline functions for client operations that differ between XWayland
  5→ * and native XDG clients. Using inline functions allows unused code paths to
  6→ * compile out when XWAYLAND is not defined.
  7→ */
  8→
  9→/* Need complete client_t definition for inline functions */
 10→#include <assert.h>
 11→#include "somewm_types.h"  /* For Client typedef and Monitor */
 12→#include "objects/client.h" /* For complete client_t definition */
 13→#include "wlr_compat.h"  /* For wlroots version compatibility */
 14→#include "common/util.h"  /* For log_debug */
 15→
 16→/* Leave these functions first; they're used in the others */
 17→static inline int
 18→client_is_x11(Client *c)
 19→{
 20→#ifdef XWAYLAND
 21→	return c->client_type == X11;
 22→#endif
 23→	return 0;
 24→}
 25→
 26→static inline struct wlr_surface *
 27→client_surface(Client *c)
 28→{
 29→#ifdef XWAYLAND
 30→	if (client_is_x11(c)) {
 31→		assert(c->surface.xwayland != NULL);
 32→		return c->surface.xwayland->surface;
 33→	}
 34→#endif
 35→	assert(c->surface.xdg != NULL);
 36→	return c->surface.xdg->surface;
 37→}
 38→
 39→static inline int
 40→toplevel_from_wlr_surface(struct wlr_surface *s, Client **pc, LayerSurface **pl)
 41→{
 42→	struct wlr_xdg_surface *xdg_surface, *tmp_xdg_surface;
 43→	struct wlr_surface *root_surface;
 44→	struct wlr_layer_surface_v1 *layer_surface;
 45→	Client *c = NULL;
 46→	LayerSurface *l = NULL;
 47→	int type = -1;
 48→#ifdef XWAYLAND
 49→	struct wlr_xwayland_surface *xsurface;
 50→#endif
 51→
 52→	if (!s)
 53→		return -1;
 54→	root_surface = wlr_surface_get_root_surface(s);
 55→
 56→#ifdef XWAYLAND
 57→	if ((xsurface = wlr_xwayland_surface_try_from_wlr_surface(root_surface))) {
 58→		c = xsurface->data;
 59→		type = c->client_type;
 60→		goto end;
 61→	}
 62→#endif
 63→
 64→	if ((layer_surface = wlr_layer_surface_v1_try_from_wlr_surface(root_surface))) {
 65→		l = layer_surface->data;
 66→		type = LayerShell;
 67→		goto end;
 68→	}
 69→
 70→	xdg_surface = wlr_xdg_surface_try_from_wlr_surface(root_surface);
 71→	while (xdg_surface) {
 72→		tmp_xdg_surface = NULL;
 73→		switch (xdg_surface->role) {
 74→		case WLR_XDG_SURFACE_ROLE_POPUP:
 75→			if (!xdg_surface->popup || !xdg_surface->popup->parent)
 76→				return -1;
 77→
 78→			tmp_xdg_surface = wlr_xdg_surface_try_from_wlr_surface(xdg_surface->popup->parent);
 79→
 80→			if (!tmp_xdg_surface)
 81→				return toplevel_from_wlr_surface(xdg_surface->popup->parent, pc, pl);
 82→
 83→			xdg_surface = tmp_xdg_surface;
 84→			break;
 85→		case WLR_XDG_SURFACE_ROLE_TOPLEVEL:
 86→			c = xdg_surface->data;
 87→			type = c->client_type;
 88→			goto end;
 89→		case WLR_XDG_SURFACE_ROLE_NONE:
 90→			return -1;
 91→		}
 92→	}
 93→
 94→end:
 95→	if (pl)
 96→		*pl = l;
 97→	if (pc)
 98→		*pc = c;
 99→	return type;
100→}
