102→/* The others */
103→static inline void
104→client_activate_surface(struct wlr_surface *s, int activated)
105→{
106→	struct wlr_xdg_toplevel *toplevel;
107→#ifdef XWAYLAND
108→	struct wlr_xwayland_surface *xsurface;
109→#endif
110→	if (!s)
111→		return;
112→#ifdef XWAYLAND
113→	if ((xsurface = wlr_xwayland_surface_try_from_wlr_surface(s))) {
114→		wlr_xwayland_surface_activate(xsurface, activated);
115→		return;
116→	}
117→#endif
118→	if ((toplevel = wlr_xdg_toplevel_try_from_wlr_surface(s)))
119→		wlr_xdg_toplevel_set_activated(toplevel, activated);
120→}
