122→static inline uint32_t
123→client_set_bounds(Client *c, int32_t width, int32_t height)
124→{
125→#ifdef XWAYLAND
126→	if (client_is_x11(c))
127→		return 0;
128→#endif
129→	if (wl_resource_get_version(c->surface.xdg->toplevel->resource) >=
130→			XDG_TOPLEVEL_CONFIGURE_BOUNDS_SINCE_VERSION && width >= 0 && height >= 0
131→			&& (c->bounds.width != width || c->bounds.height != height)) {
132→		c->bounds.width = width;
133→		c->bounds.height = height;
134→		return wlr_xdg_toplevel_set_bounds(c->surface.xdg->toplevel, width, height);
135→	}
136→	return 0;
137→}
