140→client_get_appid(Client *c)
141→{
142→#ifdef XWAYLAND
143→	if (client_is_x11(c))
144→		return c->surface.xwayland->class ? c->surface.xwayland->class : "broken";
145→#endif
146→	return c->surface.xdg->toplevel->app_id ? c->surface.xdg->toplevel->app_id : "broken";
