149→static inline void
150→client_get_clip(Client *c, struct wlr_box *clip)
151→{
152→	*clip = (struct wlr_box){
153→		.x = 0,
154→		.y = 0,
155→		.width = c->geometry.width - c->bw,
156→		.height = c->geometry.height - c->bw,
157→	};
158→
159→#ifdef XWAYLAND
160→	if (client_is_x11(c))
161→		return;
162→#endif
163→
164→	clip->x = COMPAT_XDG_SURFACE_GEOMETRY(c->surface.xdg).x;
165→	clip->y = COMPAT_XDG_SURFACE_GEOMETRY(c->surface.xdg).y;
166→}
