168→static inline void
169→client_get_geometry(Client *c, struct wlr_box *geom)
170→{
171→#ifdef XWAYLAND
172→	if (client_is_x11(c)) {
173→		geom->x = c->surface.xwayland->x;
174→		geom->y = c->surface.xwayland->y;
175→		geom->width = c->surface.xwayland->width;
176→		geom->height = c->surface.xwayland->height;
177→		return;
178→	}
179→#endif
180→	*geom = COMPAT_XDG_SURFACE_GEOMETRY(c->surface.xdg);
181→}
