183→static inline Client *
184→client_get_parent(Client *c)
185→{
186→	Client *p = NULL;
187→#ifdef XWAYLAND
188→	if (client_is_x11(c)) {
189→		if (c->surface.xwayland->parent)
190→			toplevel_from_wlr_surface(c->surface.xwayland->parent->surface, &p, NULL);
191→		return p;
192→	}
193→#endif
194→	if (c->surface.xdg->toplevel->parent)
195→		toplevel_from_wlr_surface(c->surface.xdg->toplevel->parent->base->surface, &p, NULL);
196→	return p;
197→}
