199→static inline int
200→client_has_children(Client *c)
201→{
202→#ifdef XWAYLAND
203→	if (client_is_x11(c))
204→		return !wl_list_empty(&c->surface.xwayland->children);
205→#endif
206→	/* surface.xdg->link is never empty because it always contains at least the
207→	 * surface itself. */
208→	return wl_list_length(&c->surface.xdg->link) > 1;
