211→static inline const char *
212→client_get_title(Client *c)
213→{
214→#ifdef XWAYLAND
215→	if (client_is_x11(c))
216→		return c->surface.xwayland->title ? c->surface.xwayland->title : "broken";
217→#endif
218→	return c->surface.xdg->toplevel->title ? c->surface.xdg->toplevel->title : "broken";
219→}
