221→static inline int
222→client_is_float_type(Client *c)
223→{
224→	struct wlr_xdg_toplevel *toplevel;
225→	struct wlr_xdg_toplevel_state state;
226→
227→#ifdef XWAYLAND
228→	if (client_is_x11(c)) {
229→		struct wlr_xwayland_surface *surface = c->surface.xwayland;
230→		xcb_size_hints_t *size_hints = surface->size_hints;
231→		if (surface->modal)
232→			return 1;
233→
234→#ifdef WLR_VERSION_0_19
235→		if (COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_DIALOG)
236→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_SPLASH)
237→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_TOOLBAR)
238→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_UTILITY)) {
239→			return 1;
240→		}
241→#endif
242→
243→		return size_hints && size_hints->min_width > 0 && size_hints->min_height > 0
244→			&& (size_hints->max_width == size_hints->min_width
245→				|| size_hints->max_height == size_hints->min_height);
246→	}
247→#endif
248→
249→	toplevel = c->surface.xdg->toplevel;
250→	state = toplevel->current;
251→	return toplevel->parent || (state.min_width != 0 && state.min_height != 0
252→		&& (state.min_width == state.max_width
253→			|| state.min_height == state.max_height));
254→}
