luaA_load_image(lua_State *L)
{
    const char *filename = luaL_checkstring(L, 1);
    GError *error = NULL;
    cairo_surface_t *surface = draw_load_image(L, filename, &error);

    if (surface) {
        /* Push the surface - the draw module handles the Lua userdata wrapper */
