422→{
423→	struct wlr_surface *surface;
424→	struct wlr_keyboard *kb;
425→	int surface_ready;
426→
427→	wlr_log(WLR_DEBUG, "[FOCUS-API] some_set_seat_keyboard_focus(%s/%s type=%u)",
428→		c ? client_get_title(c) : "NULL",
429→		c ? client_get_appid(c) : "NULL",
430→		c ? c->client_type : 99u);
431→
432→	if (!c) {
433→		/* NULL client = clear keyboard focus */
434→		wlr_log(WLR_DEBUG, "[FOCUS-API] clearing focus (NULL client)");
435→		wlr_seat_keyboard_notify_clear_focus(seat);
436→		return;
437→	}
438→
439→	/* Get the client's surface */
440→	surface = some_client_get_surface(c);
441→	if (!surface) {
442→		wlr_log(WLR_DEBUG, "[FOCUS-API] clearing focus (NULL surface)");
443→		wlr_seat_keyboard_notify_clear_focus(seat);
444→		return;
445→	}
446→
447→	/* Check if surface is ready for keyboard input.
448→	 * For native Wayland clients (XDGShell), check wlr_surface->mapped.
449→	 * For XWayland clients, the wlr_surface->mapped flag is set separately from
450→	 * the XWayland map event. When mapnotify() runs (triggered by XWayland map),
451→	 * the surface is ready for keyboard input even if wlr_surface->mapped is false.
452→	 * We check if c->scene exists as that indicates mapnotify() has processed
453→	 * this client and created the scene graph for it. */
454→#ifdef XWAYLAND
455→	if (c->client_type == X11) {
456→		/* XWayland: surface is ready if scene has been created */
457→		surface_ready = (c->scene != NULL);
458→		wlr_log(WLR_DEBUG, "[FOCUS-API] X11 surface_ready: scene=%p -> %d",
459→			(void*)c->scene, surface_ready);
460→	} else
461→#endif
462→	{
463→		/* Native Wayland: use standard wlr_surface->mapped check */
464→		surface_ready = surface->mapped;
465→		wlr_log(WLR_DEBUG, "[FOCUS-API] Wayland surface_ready: mapped=%d -> %d",
466→			surface->mapped, surface_ready);
467→	}
468→
469→	if (!surface_ready) {
470→		/* Surface not ready - clear seat focus to prevent input going to old window.
471→		 * When surface maps, mapnotify() will call focusclient() to set focus. */
472→		wlr_log(WLR_DEBUG, "[FOCUS-API] CLEAR: surface not ready");
473→		wlr_seat_keyboard_notify_clear_focus(seat);
474→		return;
475→	}
476→
477→	/* Only update if seat focus actually changed (avoid redundant updates) */
478→	if (seat->keyboard_state.focused_surface == surface) {
479→		wlr_log(WLR_DEBUG, "[FOCUS-API] SKIP: already focused on this surface");
480→		return;
481→	}
482→
483→	wlr_log(WLR_DEBUG, "[FOCUS-API] SENDING keyboard_enter: surface=%p old_focused=%p",
484→		(void*)surface, (void*)seat->keyboard_state.focused_surface);
485→
486→	/* Update seat keyboard focus */
487→#ifdef XWAYLAND
488→	/* Sway pattern: inform XWayland of the active seat on every focus
489→	 * change to an X11 client. Required for proper keyboard delivery. */
490→	if (c->client_type == X11) {
491→		extern struct wlr_xwayland *xwayland;
492→		wlr_xwayland_set_seat(xwayland, seat);
493→	}
494→#endif
495→	kb = wlr_seat_get_keyboard(seat);
496→	if (kb) {
497→		wlr_seat_keyboard_notify_enter(seat, surface,
498→		                               kb->keycodes,
499→		                               kb->num_keycodes,
500→		                               &kb->modifiers);
501→	} else {
502→		/* Send keyboard enter even without a keyboard device (Sway pattern).
503→		 * Without this, XWayland clients and games never receive keyboard
504→		 * focus when this path is taken via Lua client.focus = c */
505→		wlr_seat_keyboard_notify_enter(seat, surface, NULL, 0, NULL);
506→	}
507→	wlr_log(WLR_DEBUG, "[FOCUS-API] DONE: seat_focused=%p match=%d",
508→		(void*)seat->keyboard_state.focused_surface,
509→		seat->keyboard_state.focused_surface == surface);
510→}
