 56→static void unmanaged_handle_map(struct wl_listener *listener, void *data) {
 57→	struct sway_xwayland_unmanaged *surface =
 58→		wl_container_of(listener, surface, map);
 59→	struct wlr_xwayland_surface *xsurface = surface->wlr_xwayland_surface;
 60→
 61→	surface->surface_scene = wlr_scene_surface_create(root->layers.unmanaged,
 62→		xsurface->surface);
 63→
 64→	if (surface->surface_scene) {
 65→		scene_descriptor_assign(&surface->surface_scene->buffer->node,
 66→			SWAY_SCENE_DESC_XWAYLAND_UNMANAGED, surface);
 67→		wlr_scene_node_set_position(&surface->surface_scene->buffer->node,
 68→			xsurface->x, xsurface->y);
 69→
 70→		wl_signal_add(&xsurface->events.set_geometry, &surface->set_geometry);
 71→		surface->set_geometry.notify = unmanaged_handle_set_geometry;
 72→	}
 73→
 74→	if (wlr_xwayland_surface_override_redirect_wants_focus(xsurface)) {
 75→		struct sway_seat *seat = input_manager_current_seat();
 76→		struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
 77→		wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
 78→		seat_set_focus_surface(seat, xsurface->surface, false);
 79→	}
