 83→	struct sway_xwayland_unmanaged *surface =
 84→		wl_container_of(listener, surface, unmap);
 85→	struct wlr_xwayland_surface *xsurface = surface->wlr_xwayland_surface;
 86→
 87→	if (surface->surface_scene) {
 88→		wl_list_remove(&surface->set_geometry.link);
 89→
 90→		wlr_scene_node_destroy(&surface->surface_scene->buffer->node);
 91→		surface->surface_scene = NULL;
 92→	}
