 94→	struct sway_seat *seat = input_manager_current_seat();
 95→	if (seat->wlr_seat->keyboard_state.focused_surface == xsurface->surface) {
 96→		// This simply returns focus to the parent surface if there's one available.
 97→		// This seems to handle JetBrains issues.
 98→		if (xsurface->parent && xsurface->parent->surface
 99→				&& wlr_xwayland_surface_override_redirect_wants_focus(xsurface->parent)) {
100→			seat_set_focus_surface(seat, xsurface->parent->surface, false);
101→			return;
102→		}
103→
104→		// Restore focus
105→		struct sway_node *previous = seat_get_focus_inactive(seat, &root->node);
106→		if (previous) {
107→			// Hack to get seat to re-focus the return value of get_focus
108→			seat_set_focus(seat, NULL);
109→			seat_set_focus(seat, previous);
110→		}
111→	}
112→}
