164→static void unmanaged_handle_override_redirect(struct wl_listener *listener, void *data) {
165→	struct sway_xwayland_unmanaged *surface =
166→		wl_container_of(listener, surface, override_redirect);
167→	struct wlr_xwayland_surface *xsurface = surface->wlr_xwayland_surface;
168→
169→	bool associated = xsurface->surface != NULL;
170→	bool mapped = associated && xsurface->surface->mapped;
171→	if (mapped) {
172→		unmanaged_handle_unmap(&surface->unmap, NULL);
173→	}
174→	if (associated) {
175→		unmanaged_handle_dissociate(&surface->dissociate, NULL);
176→	}
177→
178→	unmanaged_handle_destroy(&surface->destroy, NULL);
179→	xsurface->data = NULL;
180→
181→	struct sway_xwayland_view *xwayland_view = create_xwayland_view(xsurface);
182→	if (associated) {
183→		handle_associate(&xwayland_view->associate, NULL);
184→	}
185→	if (mapped) {
186→		handle_map(&xwayland_view->map, xsurface);
187→	}
188→}
