190→static struct sway_xwayland_unmanaged *create_unmanaged(
191→		struct wlr_xwayland_surface *xsurface) {
192→	struct sway_xwayland_unmanaged *surface =
193→		calloc(1, sizeof(struct sway_xwayland_unmanaged));
194→	if (surface == NULL) {
195→		sway_log(SWAY_ERROR, "Allocation failed");
196→		return NULL;
197→	}
198→
199→	surface->wlr_xwayland_surface = xsurface;
200→
201→	wl_signal_add(&xsurface->events.request_configure,
202→		&surface->request_configure);
203→	surface->request_configure.notify = unmanaged_handle_request_configure;
204→	wl_signal_add(&xsurface->events.associate, &surface->associate);
205→	surface->associate.notify = unmanaged_handle_associate;
206→	wl_signal_add(&xsurface->events.dissociate, &surface->dissociate);
207→	surface->dissociate.notify = unmanaged_handle_dissociate;
208→	wl_signal_add(&xsurface->events.destroy, &surface->destroy);
209→	surface->destroy.notify = unmanaged_handle_destroy;
210→	wl_signal_add(&xsurface->events.set_override_redirect, &surface->override_redirect);
211→	surface->override_redirect.notify = unmanaged_handle_override_redirect;
212→	wl_signal_add(&xsurface->events.request_activate, &surface->request_activate);
213→	surface->request_activate.notify = unmanaged_handle_request_activate;
214→
215→	return surface;
216→}
