310→static bool wants_floating(struct sway_view *view) {
311→	if (xwayland_view_from_view(view) == NULL) {
312→		return false;
313→	}
314→	struct wlr_xwayland_surface *surface = view->wlr_xwayland_surface;
315→	struct sway_xwayland *xwayland = &server.xwayland;
316→
317→	if (surface->modal) {
318→		return true;
319→	}
320→
321→	for (size_t i = 0; i < surface->window_type_len; ++i) {
322→		xcb_atom_t type = surface->window_type[i];
323→		if (type == xwayland->atoms[NET_WM_WINDOW_TYPE_DIALOG] ||
324→				type == xwayland->atoms[NET_WM_WINDOW_TYPE_UTILITY] ||
325→				type == xwayland->atoms[NET_WM_WINDOW_TYPE_TOOLBAR] ||
326→				type == xwayland->atoms[NET_WM_WINDOW_TYPE_SPLASH]) {
327→			return true;
328→		}
329→	}
330→
331→	xcb_size_hints_t *size_hints = surface->size_hints;
332→	if (size_hints != NULL &&
333→			size_hints->min_width > 0 && size_hints->min_height > 0 &&
334→			(size_hints->max_width == size_hints->min_width ||
335→			size_hints->max_height == size_hints->min_height)) {
336→		return true;
337→	}
338→
339→	return false;
340→}
