415→static void handle_commit(struct wl_listener *listener, void *data) {
416→	struct sway_xwayland_view *xwayland_view =
417→		wl_container_of(listener, xwayland_view, commit);
418→	struct sway_view *view = &xwayland_view->view;
419→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
420→	struct wlr_surface_state *state = &xsurface->surface->current;
421→
422→	struct wlr_box new_geo = {0};
423→	new_geo.width = state->width;
424→	new_geo.height = state->height;
425→
426→	bool new_size = new_geo.width != view->geometry.width ||
427→			new_geo.height != view->geometry.height;
428→
429→	if (new_size) {
430→		// The client changed its surface size in this commit. For floating
431→		// containers, we resize the container to match. For tiling containers,
432→		// we only recenter the surface.
433→		memcpy(&view->geometry, &new_geo, sizeof(struct wlr_box));
434→		if (container_is_floating(view->container)) {
435→			view_update_size(view);
436→			transaction_commit_dirty_client();
437→		}
438→
439→		view_center_and_clip_surface(view);
440→	}
441→
442→	if (view->container->node.instruction) {
443→		bool successful = transaction_notify_view_ready_by_geometry(view,
444→				xsurface->x, xsurface->y, state->width, state->height);
445→
446→		// If we saved the view and this commit isn't what we're looking for
447→		// that means the user will never actually see the buffers submitted to
448→		// us here. Just send frame done events to these surfaces so they can
449→		// commit another time for us.
450→		if (view->saved_surface_tree && !successful) {
451→			view_send_frame_done(view);
452→		}
453→	}
454→}
