517→static void handle_map(struct wl_listener *listener, void *data) {
518→	struct sway_xwayland_view *xwayland_view =
519→		wl_container_of(listener, xwayland_view, map);
520→	struct sway_view *view = &xwayland_view->view;
521→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
522→
523→	view->natural_width = xsurface->width;
524→	view->natural_height = xsurface->height;
525→
526→	// Wire up the commit listener here, because xwayland map/unmap can change
527→	// the underlying wlr_surface
528→	wl_signal_add(&xsurface->surface->events.commit, &xwayland_view->commit);
529→	xwayland_view->commit.notify = handle_commit;
530→
531→	// Put it back into the tree
532→	view_map(view, xsurface->surface, xsurface->fullscreen, NULL, false);
533→
534→	xwayland_view->surface_tree = wlr_scene_subsurface_tree_create(
535→		xwayland_view->view.content_tree, xsurface->surface);
536→
537→	if (xwayland_view->surface_tree) {
538→		xwayland_view->surface_tree_destroy.notify = handle_surface_tree_destroy;
539→		wl_signal_add(&xwayland_view->surface_tree->node.events.destroy,
540→			&xwayland_view->surface_tree_destroy);
541→	}
542→
543→	xwayland_view->image_capture_scene_surface =
544→		wlr_scene_surface_create(&xwayland_view->view.image_capture_scene->tree, xsurface->surface);
545→
546→	transaction_commit_dirty();
547→}
