553→		wl_container_of(listener, xwayland_view, override_redirect);
554→	struct sway_view *view = &xwayland_view->view;
555→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
556→
557→	bool associated = xsurface->surface != NULL;
558→	bool mapped = associated && xsurface->surface->mapped;
559→	if (mapped) {
560→		handle_unmap(&xwayland_view->unmap, NULL);
561→	}
