637→static void handle_request_move(struct wl_listener *listener, void *data) {
638→	struct sway_xwayland_view *xwayland_view =
639→		wl_container_of(listener, xwayland_view, request_move);
640→	struct sway_view *view = &xwayland_view->view;
641→	struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
642→	if (xsurface->surface == NULL || !xsurface->surface->mapped) {
643→		return;
644→	}
