  38→static void seat_device_destroy(struct sway_seat_device *seat_device) {
  39→	if (!seat_device) {
  40→		return;
  41→	}
  42→
  43→	sway_keyboard_destroy(seat_device->keyboard);
  44→	sway_tablet_destroy(seat_device->tablet);
  45→	sway_tablet_pad_destroy(seat_device->tablet_pad);
  46→	sway_switch_destroy(seat_device->switch_device);
  47→	wlr_cursor_detach_input_device(seat_device->sway_seat->cursor->cursor,
  48→		seat_device->input_device->wlr_device);
