 114→/**
 115→ * Activate all views within this container recursively.
 116→ */
 117→static void seat_send_activate(struct sway_node *node, struct sway_seat *seat) {
 118→	if (node_is_view(node)) {
 119→		if (!seat_is_input_allowed(seat, node->sway_container->view->surface)) {
 120→			sway_log(SWAY_DEBUG, "Refusing to set focus, input is inhibited");
 121→			return;
 122→		}
 123→		view_set_activated(node->sway_container->view, true);
 124→	} else {
 125→		list_t *children = node_get_children(node);
 126→		for (int i = 0; i < children->length; ++i) {
 127→			struct sway_container *child = children->items[i];
 128→			seat_send_activate(&child->node, seat);
 129→		}
 130→	}
 131→}
