 133→static struct sway_keyboard *sway_keyboard_for_wlr_keyboard(
 134→		struct sway_seat *seat, struct wlr_keyboard *wlr_keyboard) {
 135→	struct sway_seat_device *seat_device;
 136→	wl_list_for_each(seat_device, &seat->devices, link) {
 137→		struct sway_input_device *input_device = seat_device->input_device;
 138→		if (input_device->wlr_device->type != WLR_INPUT_DEVICE_KEYBOARD) {
 139→			continue;
 140→		}
 141→		if (input_device->wlr_device == &wlr_keyboard->base) {
 142→			return seat_device->keyboard;
 143→		}
 144→	}
 145→	struct sway_keyboard_group *group;
 146→	wl_list_for_each(group, &seat->keyboard_groups, link) {
 147→		struct sway_input_device *input_device =
 148→			group->seat_device->input_device;
 149→		if (input_device->wlr_device == &wlr_keyboard->base) {
 150→			return group->seat_device->keyboard;
 151→		}
 152→	}
 153→	return NULL;
 154→}
