 156→static void seat_keyboard_notify_enter(struct sway_seat *seat,
 157→		struct wlr_surface *surface) {
 158→	struct wlr_keyboard *keyboard = wlr_seat_get_keyboard(seat->wlr_seat);
 159→	if (!keyboard) {
 160→		wlr_seat_keyboard_notify_enter(seat->wlr_seat, surface, NULL, 0, NULL);
 161→		return;
 162→	}
 163→
 164→	struct sway_keyboard *sway_keyboard =
 165→		sway_keyboard_for_wlr_keyboard(seat, keyboard);
 166→	assert(sway_keyboard && "Cannot find sway_keyboard for seat keyboard");
 167→
 168→	struct sway_shortcut_state *state = &sway_keyboard->state_pressed_sent;
 169→	wlr_seat_keyboard_notify_enter(seat->wlr_seat, surface,
 170→			state->pressed_keycodes, state->npressed, &keyboard->modifiers);
 171→}
