 181→/**
 182→ * If con is a view, set it as active and enable keyboard input.
 183→ * If con is a container, set all child views as active and don't enable
 184→ * keyboard input on any.
 185→ */
 186→static void seat_send_focus(struct sway_node *node, struct sway_seat *seat) {
 187→	seat_send_activate(node, seat);
 188→
 189→	struct sway_view *view = node->type == N_CONTAINER ?
 190→		node->sway_container->view : NULL;
 191→
 192→	if (view && seat_is_input_allowed(seat, view->surface)) {
 193→#if WLR_HAS_XWAYLAND
 194→		if (view->type == SWAY_VIEW_XWAYLAND) {
 195→			struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
 196→			wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
 197→		}
 198→#endif
 199→
 200→		seat_keyboard_notify_enter(seat, view->surface);
 201→		seat_tablet_pads_set_focus(seat, view->surface);
 202→		sway_input_method_relay_set_focus(&seat->im_relay, view->surface);
 203→
 204→		struct wlr_pointer_constraint_v1 *constraint =
 205→			wlr_pointer_constraints_v1_constraint_for_surface(
 206→				server.pointer_constraints, view->surface, seat->wlr_seat);
 207→		sway_cursor_constrain(seat->cursor, constraint);
 208→	}
 209→}
