 362→static void drag_icon_update_position(struct sway_seat *seat, struct wlr_scene_node *node) {
 363→	struct wlr_drag_icon *wlr_icon = scene_descriptor_try_get(node, SWAY_SCENE_DESC_DRAG_ICON);
 364→	struct wlr_cursor *cursor = seat->cursor->cursor;
 365→
 366→	switch (wlr_icon->drag->grab_type) {
 367→	case WLR_DRAG_GRAB_KEYBOARD:
 368→		return;
 369→	case WLR_DRAG_GRAB_KEYBOARD_POINTER:
 370→		wlr_scene_node_set_position(node, cursor->x, cursor->y);
 371→		break;
 372→	case WLR_DRAG_GRAB_KEYBOARD_TOUCH:;
 373→		struct wlr_touch_point *point =
 374→			wlr_seat_touch_get_point(seat->wlr_seat, wlr_icon->drag->touch_id);
 375→		if (point == NULL) {
 376→			return;
 377→		}
 378→		wlr_scene_node_set_position(node, seat->touch_x, seat->touch_y);
 379→	}
 380→}
