 389→static void drag_handle_destroy(struct wl_listener *listener, void *data) {
 390→	struct sway_drag *drag = wl_container_of(listener, drag, destroy);
 391→
 392→	// Focus enter isn't sent during drag, so refocus the focused node, layer
 393→	// surface or unmanaged surface.
 394→	struct sway_seat *seat = drag->seat;
 395→	struct sway_node *focus = seat_get_focus(seat);
 396→	if (focus) {
 397→		seat_set_focus(seat, NULL);
 398→		seat_set_focus(seat, focus);
 399→	} else if (seat->focused_layer) {
 400→		struct wlr_layer_surface_v1 *layer = seat->focused_layer;
 401→		seat_set_focus_layer(seat, NULL);
 402→		seat_set_focus_layer(seat, layer);
 403→	} else {
 404→		struct wlr_surface *unmanaged = seat->wlr_seat->keyboard_state.focused_surface;
 405→		seat_set_focus_surface(seat, NULL, false);
 406→		seat_set_focus_surface(seat, unmanaged, false);
 407→	}
 408→
 409→	drag->wlr_drag->data = NULL;
 410→	wl_list_remove(&drag->destroy.link);
 411→	free(drag);
 412→}
