 414→static void handle_request_start_drag(struct wl_listener *listener,
 415→		void *data) {
 416→	struct sway_seat *seat = wl_container_of(listener, seat, request_start_drag);
 417→	struct wlr_seat_request_start_drag_event *event = data;
 418→
 419→	if (wlr_seat_validate_pointer_grab_serial(seat->wlr_seat,
 420→			event->origin, event->serial)) {
 421→		wlr_seat_start_pointer_drag(seat->wlr_seat, event->drag, event->serial);
 422→		return;
 423→	}
 424→
 425→	struct wlr_touch_point *point;
 426→	if (wlr_seat_validate_touch_grab_serial(seat->wlr_seat,
 427→			event->origin, event->serial, &point)) {
 428→		wlr_seat_start_touch_drag(seat->wlr_seat,
 429→			event->drag, event->serial, point);
 430→		return;
 431→	}
 432→
 433→	// TODO: tablet grabs
 434→
 435→	sway_log(SWAY_DEBUG, "Ignoring start_drag request: "
 436→		"could not validate pointer or touch serial %" PRIu32, event->serial);
 437→	wlr_data_source_destroy(event->drag->source);
 438→}
 439→
 440→static void handle_start_drag(struct wl_listener *listener, void *data) {
 441→	struct sway_seat *seat = wl_container_of(listener, seat, start_drag);
 442→	struct wlr_drag *wlr_drag = data;
 443→
 444→	struct sway_drag *drag = calloc(1, sizeof(struct sway_drag));
 445→	if (drag == NULL) {
 446→		sway_log(SWAY_ERROR, "Allocation failed");
 447→		return;
 448→	}
 449→	drag->seat = seat;
 450→	drag->wlr_drag = wlr_drag;
 451→	wlr_drag->data = drag;
 452→
 453→	drag->destroy.notify = drag_handle_destroy;
 454→	wl_signal_add(&wlr_drag->events.destroy, &drag->destroy);
 455→
 456→	struct wlr_drag_icon *wlr_drag_icon = wlr_drag->icon;
 457→	if (wlr_drag_icon != NULL) {
 458→		struct wlr_scene_tree *tree = wlr_scene_drag_icon_create(seat->drag_icons, wlr_drag_icon);
 459→		if (!tree) {
 460→			sway_log(SWAY_ERROR, "Failed to allocate a drag icon scene tree");
 461→			return;
 462→		}
 463→
 464→		if (!scene_descriptor_assign(&tree->node, SWAY_SCENE_DESC_DRAG_ICON,
 465→				wlr_drag_icon)) {
 466→			sway_log(SWAY_ERROR, "Failed to allocate a drag icon scene descriptor");
 467→			wlr_scene_node_destroy(&tree->node);
 468→			return;
 469→		}
 470→
 471→		drag_icon_update_position(seat, &tree->node);
 472→	}
 473→	seatop_begin_default(seat);
 474→}
