 604→static void seat_update_capabilities(struct sway_seat *seat) {
 605→	uint32_t caps = 0;
 606→	uint32_t previous_caps = seat->wlr_seat->capabilities;
 607→	struct sway_seat_device *seat_device;
 608→	wl_list_for_each(seat_device, &seat->devices, link) {
 609→		switch (seat_device->input_device->wlr_device->type) {
 610→		case WLR_INPUT_DEVICE_KEYBOARD:
 611→			caps |= WL_SEAT_CAPABILITY_KEYBOARD;
 612→			break;
 613→		case WLR_INPUT_DEVICE_POINTER:
 614→			caps |= WL_SEAT_CAPABILITY_POINTER;
 615→			break;
 616→		case WLR_INPUT_DEVICE_TOUCH:
 617→			caps |= WL_SEAT_CAPABILITY_TOUCH;
 618→			break;
 619→		case WLR_INPUT_DEVICE_TABLET:
 620→			caps |= WL_SEAT_CAPABILITY_POINTER;
 621→			break;
 622→		case WLR_INPUT_DEVICE_SWITCH:
 623→		case WLR_INPUT_DEVICE_TABLET_PAD:
 624→			break;
 625→		}
 626→	}
 627→
 628→	// Hide cursor if seat doesn't have pointer capability.
 629→	// We must call cursor_set_image while the wlr_seat has the capabilities
 630→	// otherwise it's a no op.
 631→	if ((caps & WL_SEAT_CAPABILITY_POINTER) == 0) {
 632→		cursor_set_image(seat->cursor, NULL, NULL);
 633→		wlr_seat_set_capabilities(seat->wlr_seat, caps);
 634→	} else {
 635→		wlr_seat_set_capabilities(seat->wlr_seat, caps);
 636→		if ((previous_caps & WL_SEAT_CAPABILITY_POINTER) == 0) {
 637→			cursor_set_image(seat->cursor, "default", NULL);
 638→		}
 639→	}
 640→}
