 670→static bool is_touch_or_tablet_tool(struct sway_seat_device *seat_device) {
 671→	switch (seat_device->input_device->wlr_device->type) {
 672→	case WLR_INPUT_DEVICE_TOUCH:
 673→	case WLR_INPUT_DEVICE_TABLET:
 674→		return true;
 675→	default:
 676→		return false;
 677→	}
 678→}
 679→
 680→static void seat_apply_input_mapping(struct sway_seat *seat,
 681→		struct sway_seat_device *sway_device) {
 682→	struct input_config *ic =
 683→		input_device_get_config(sway_device->input_device);
 684→
 685→	switch (sway_device->input_device->wlr_device->type) {
 686→	case WLR_INPUT_DEVICE_POINTER:
 687→	case WLR_INPUT_DEVICE_TOUCH:
 688→	case WLR_INPUT_DEVICE_TABLET:
 689→		break;
 690→	default:
 691→		return; // these devices don't support mappings
 692→	}
 693→
 694→	sway_log(SWAY_DEBUG, "Applying input mapping to %s",
 695→		sway_device->input_device->identifier);
 696→
 697→	const char *mapped_to_output = ic == NULL ? NULL : ic->mapped_to_output;
 698→	struct wlr_box *mapped_to_region = ic == NULL ? NULL : ic->mapped_to_region;
 699→	enum input_config_mapped_to mapped_to =
 700→		ic == NULL ? MAPPED_TO_DEFAULT : ic->mapped_to;
 701→
 702→	switch (mapped_to) {
 703→	case MAPPED_TO_DEFAULT:;
 704→		/*
 705→		 * If the wlroots backend provides an output name, use that.
 706→		 *
 707→		 * Otherwise, try to map built-in touch and pointer devices to the
 708→		 * built-in output.
 709→		 */
 710→		struct wlr_input_device *dev = sway_device->input_device->wlr_device;
 711→		switch (dev->type) {
 712→		case WLR_INPUT_DEVICE_POINTER:
 713→			mapped_to_output = wlr_pointer_from_input_device(dev)->output_name;
 714→			break;
 715→		case WLR_INPUT_DEVICE_TOUCH:
 716→			mapped_to_output = wlr_touch_from_input_device(dev)->output_name;
 717→			break;
 718→		default:
 719→			mapped_to_output = NULL;
 720→			break;
 721→		}
 722→#if WLR_HAS_LIBINPUT_BACKEND
 723→		if (mapped_to_output == NULL && is_touch_or_tablet_tool(sway_device) &&
 724→				sway_libinput_device_is_builtin(sway_device->input_device)) {
 725→			mapped_to_output = get_builtin_output_name();
 726→			if (mapped_to_output) {
 727→				sway_log(SWAY_DEBUG, "Auto-detected output '%s' for device '%s'",
 728→					mapped_to_output, sway_device->input_device->identifier);
 729→			}
 730→		}
 731→#else
 732→		(void)is_touch_or_tablet_tool;
 733→		(void)get_builtin_output_name;
 734→#endif
 735→		if (mapped_to_output == NULL) {
 736→			return;
 737→		}
 738→		/* fallthrough */
 739→	case MAPPED_TO_OUTPUT:
 740→		sway_log(SWAY_DEBUG, "Mapping input device %s to output %s",
 741→			sway_device->input_device->identifier, mapped_to_output);
 742→		if (strcmp("*", mapped_to_output) == 0) {
 743→			wlr_cursor_map_input_to_output(seat->cursor->cursor,
 744→				sway_device->input_device->wlr_device, NULL);
 745→			wlr_cursor_map_input_to_region(seat->cursor->cursor,
 746→				sway_device->input_device->wlr_device, NULL);
 747→			sway_log(SWAY_DEBUG, "Reset output mapping");
 748→			return;
 749→		}
 750→		struct sway_output *output = output_by_name_or_id(mapped_to_output);
 751→		if (!output) {
 752→			sway_log(SWAY_DEBUG, "Requested output %s for device %s isn't present",
 753→				mapped_to_output, sway_device->input_device->identifier);
 754→			return;
 755→		}
 756→		wlr_cursor_map_input_to_output(seat->cursor->cursor,
 757→			sway_device->input_device->wlr_device, output->wlr_output);
 758→		wlr_cursor_map_input_to_region(seat->cursor->cursor,
 759→			sway_device->input_device->wlr_device, NULL);
 760→		sway_log(SWAY_DEBUG,
 761→			"Mapped to output %s", output->wlr_output->name);
 762→		return;
