 768→		wlr_cursor_map_input_to_output(seat->cursor->cursor,
 769→			sway_device->input_device->wlr_device, NULL);
 770→		wlr_cursor_map_input_to_region(seat->cursor->cursor,
 771→			sway_device->input_device->wlr_device, mapped_to_region);
