Perfect! Now I have all the information I need. Let me create a comprehensive report.

## Summary: Sway's XWayland Focus Delivery Implementation

Based on my analysis of the Sway compositor's XWayland handling, here are the key findings:

### 1. **Managed XWayland Surface Focus Flow** (lines 517-547 in xwayland.c)

When an XWayland surface maps via `handle_map()`:
```c
// Line 517-547: xwayland.c
static void handle_map(struct wl_listener *listener, void *data) {
    struct sway_xwayland_view *xwayland_view = ...
    struct sway_view *view = &xwayland_view->view;
    struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;

    // Store natural dimensions
    view->natural_width = xsurface->width;
    view->natural_height = xsurface->height;

    // Wire up commit listener AFTER map
    wl_signal_add(&xsurface->surface->events.commit, &xwayland_view->commit);
    xwayland_view->commit.notify = handle_commit;

    // Put surface into scene tree
    view_map(view, xsurface->surface, xsurface->fullscreen, NULL, false);

    // Create subsurface tree
    xwayland_view->surface_tree = wlr_scene_subsurface_tree_create(
        xwayland_view->view.content_tree, xsurface->surface);

    // Create image capture surface
    xwayland_view->image_capture_scene_surface = 
        wlr_scene_surface_create(...);

    transaction_commit_dirty();  // Initiate transaction
}
```

**Key point**: The commit listener is WIRED UP AFTER map, not before.

### 2. **view_map() Function - Where Focus is Determined** (lines 765-909 in view.c)

When `view_map()` is called, it:
1. Creates the container and assigns workspace
2. Executes placement rules via `view_execute_criteria()`
3. **Checks if focus should be set** (lines 898-909):

```c
// Line 898-909: view.c
bool set_focus = should_focus(view);

#if WLR_HAS_XWAYLAND
struct wlr_xwayland_surface *xsurface;
if ((xsurface = wlr_xwayland_surface_try_from_wlr_surface(wlr_surface))) {
    set_focus &= wlr_xwayland_surface_icccm_input_model(xsurface) !=
            WLR_ICCCM_INPUT_MODEL_NONE;
}
#endif

if (set_focus) {
    input_manager_set_focus(&view->container->node);
}
```

This checks ICCCM input model to verify if the surface accepts focus.

### 3. **The Focus Delivery Chain** (seats.c lines 186-209)

When focus is set, `seat_send_focus()` is called:

```c
// Line 186-209: seat.c
static void seat_send_focus(struct sway_node *node, struct sway_seat *seat) {
    seat_send_activate(node, seat);

    struct sway_view *view = node->type == N_CONTAINER ?
        node->sway_container->view : NULL;

    if (view && seat_is_input_allowed(seat, view->surface)) {
#if WLR_HAS_XWAYLAND
        // **CRITICAL**: Call wlr_xwayland_set_seat FIRST
        if (view->type == SWAY_VIEW_XWAYLAND) {
            struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
            wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
        }
#endif

        // Then deliver keyboard enter
        seat_keyboard_notify_enter(seat, view->surface);
        seat_tablet_pads_set_focus(seat, view->surface);
        sway_input_method_relay_set_focus(&seat->im_relay, view->surface);

        // Constrain pointer if needed
        struct wlr_pointer_constraint_v1 *constraint = ...
        sway_cursor_constrain(seat->cursor, constraint);
    }
}
```

### 4. **seat_keyboard_notify_enter() - Handles NULL Keyboard** (lines 156-171)

**IMPORTANT FOR NVIDIA**: This function sends keyboard enter EVEN IF no keyboard is present:

```c
// Line 156-171: seat.c
static void seat_keyboard_notify_enter(struct sway_seat *seat,
        struct wlr_surface *surface) {
    struct wlr_keyboard *keyboard = wlr_seat_get_keyboard(seat->wlr_seat);
    if (!keyboard) {
        // **CRITICAL**: Still sends enter with NULL keyboard!
        wlr_seat_keyboard_notify_enter(seat->wlr_seat, surface, NULL, 0, NULL);
        return;
    }

    struct sway_keyboard *sway_keyboard = ...
    struct sway_shortcut_state *state = &sway_keyboard->state_pressed_sent;
    wlr_seat_keyboard_notify_enter(seat->wlr_seat, surface,
            state->pressed_keycodes, state->npressed, &keyboard->modifiers);
}
```

### 5. **Override-Redirect/Unmanaged Windows (Games, Dialogs)** (lines 56-79)

For override-redirect windows (used by games, Wine, popups):

```c
// Line 56-79: xwayland.c
static void unmanaged_handle_map(struct wl_listener *listener, void *data) {
    struct sway_xwayland_unmanaged *surface = ...
    struct wlr_xwayland_surface *xsurface = surface->wlr_xwayland_surface;

    // Create scene surface
    surface->surface_scene = wlr_scene_surface_create(root->layers.unmanaged,
        xsurface->surface);

    if (surface->surface_scene) {
        // Assign scene descriptor
        scene_descriptor_assign(&surface->surface_scene->buffer->node,
            SWAY_SCENE_DESC_XWAYLAND_UNMANAGED, surface);
        wlr_scene_node_set_position(&surface->surface_scene->buffer->node,
            xsurface->x, xsurface->y);

        // Monitor geometry changes
        wl_signal_add(&xsurface->events.set_geometry, &surface->set_geometry);
        surface->set_geometry.notify = unmanaged_handle_set_geometry;
    }

    // **CRITICAL FOR GAMES**: Check if override_redirect wants focus
    if (wlr_xwayland_surface_override_redirect_wants_focus(xsurface)) {
        struct sway_seat *seat = input_manager_current_seat();
        struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
        wlr_xwayland_set_seat(xwayland, seat->wlr_seat);  // Set seat first
        seat_set_focus_surface(seat, xsurface->surface, false);
    }
}
```

**Game-specific behavior**: Override-redirect surfaces automatically get focus if `wlr_xwayland_surface_override_redirect_wants_focus()` returns true. This handles menus, dialogs, and game windows that manage their own focus.

### 6. **XWayland Request Activate Handler** (lines 669-680)

When a client explicitly requests activation:

```c
// Line 669-680: xwayland.c
static void handle_request_activate(struct wl_listener *listener, void *data) {
    struct sway_xwayland_view *xwayland_view = ...
    struct sway_view *view = &xwayland_view->view;
    struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
    if (xsurface->surface == NULL || !xsurface->surface->mapped) {
        return;  // Don't act if surface not mapped yet
    }
    view_request_activate(view, NULL);

    transaction_commit_dirty();
}
```

### 7. **Commit Handling - NO Focus Re-delivery** (lines 415-454)

The commit handler DOES NOT re-deliver focus:

```c
// Line 415-454: xwayland.c
static void handle_commit(struct wl_listener *listener, void *data) {
    struct sway_xwayland_view *xwayland_view = ...
    struct sway_view *view = &xwayland_view->view;
    struct wlr_xwayland_surface *xsurface = view->wlr_xwayland_surface;
    struct wlr_surface_state *state = &xsurface->surface->current;

    // Handle size changes
    struct wlr_box new_geo = {0};
    new_geo.width = state->width;
    new_geo.height = state->height;

    bool new_size = new_geo.width != view->geometry.width ||
            new_geo.height != view->geometry.height;

    if (new_size) {
