3947→
3948→	/* Check if our fd has events ready */
3949→	return wl_source->poll_fd.revents & G_IO_IN;
3950→}
3951→
3952→/* WaylandSource dispatch callback - process Wayland events */
3953→static gboolean
3954→wayland_source_dispatch(GSource *source, GSourceFunc callback, gpointer user_data)
3955→{
3956→	WaylandSource *wl_source = (WaylandSource *)source;
3957→
3958→	/* Dispatch all pending Wayland events (non-blocking)
3959→	 * This processes backend events, client requests, etc. */
3960→	wl_event_loop_dispatch(wl_source->loop, 0);
3961→
3962→	return G_SOURCE_CONTINUE;
3963→}
3964→
3965→/* WaylandSource function table */
3966→static GSourceFuncs wayland_source_funcs = {
3967→	wayland_source_prepare,
3968→	wayland_source_check,
3969→	wayland_source_dispatch,
3970→	NULL,  /* finalize */
3971→	NULL,  /* closure_callback */
3972→	NULL   /* closure_marshal */
