3975→/* Create GSource for Wayland event loop */
3976→static GSource *
3977→create_wayland_source(struct wl_event_loop *loop)
3978→{
3979→	WaylandSource *wl_source;
3980→	GSource *source;
3981→	int fd;
3982→
3983→	/* Get the Wayland event loop's aggregate file descriptor */
3984→	fd = wl_event_loop_get_fd(loop);
3985→	if (fd < 0) {
3986→		fprintf(stderr, "ERROR: Failed to get Wayland event loop fd\n");
3987→		return NULL;
3988→	}
3989→
3990→	/* Create our custom GSource */
3991→	source = g_source_new(&wayland_source_funcs, sizeof(WaylandSource));
3992→	wl_source = (WaylandSource *)source;
3993→	wl_source->loop = loop;
