228→static inline int
229→client_is_float_type(Client *c)
230→{
231→	struct wlr_xdg_toplevel *toplevel;
232→	struct wlr_xdg_toplevel_state state;
233→
234→#ifdef XWAYLAND
235→	if (client_is_x11(c)) {
236→		struct wlr_xwayland_surface *surface = c->surface.xwayland;
237→		xcb_size_hints_t *size_hints = surface->size_hints;
238→		if (surface->modal)
239→			return 1;
240→
241→#ifdef WLR_VERSION_0_19
242→		if (COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_DIALOG)
243→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_SPLASH)
244→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_TOOLBAR)
245→				|| COMPAT_XWAYLAND_HAS_WINDOW_TYPE(surface, WLR_XWAYLAND_NET_WM_WINDOW_TYPE_UTILITY)) {
246→			return 1;
247→		}
248→#endif
249→
250→		return size_hints && size_hints->min_width > 0 && size_hints->min_height > 0
251→			&& (size_hints->max_width == size_hints->min_width
252→				|| size_hints->max_height == size_hints->min_height);
253→	}
254→#endif
255→
256→	toplevel = c->surface.xdg->toplevel;
257→	state = toplevel->current;
258→	return toplevel->parent || (state.min_width != 0 && state.min_height != 0
259→		&& (state.min_width == state.max_width
260→			|| state.min_height == state.max_height));
261→}
