279→static inline int
280→client_is_stopped(Client *c)
281→{
282→	int pid;
283→	siginfo_t in = {0};
284→#ifdef XWAYLAND
285→	if (client_is_x11(c))
286→		return 0;
287→#endif
288→
289→	wl_client_get_credentials(c->surface.xdg->client->client, &pid, NULL, NULL);
290→	if (waitid(P_PID, pid, &in, WNOHANG|WCONTINUED|WSTOPPED|WNOWAIT) < 0) {
291→		/* This process is not our child process, while is very unlikely that
292→		 * it is stopped, in order to do not skip frames, assume that it is. */
293→		if (errno == ECHILD)
294→			return 1;
295→	} else if (in.si_pid) {
296→		if (in.si_code == CLD_STOPPED || in.si_code == CLD_TRAPPED)
297→			return 1;
298→		if (in.si_code == CLD_CONTINUED)
299→			return 0;
300→	}
301→
302→	return 0;
303→}
