3833→/* Apply geometry to wlroots scene graph - Wayland-specific rendering layer.
3834→ * This function ONLY updates wlroots; it does NOT modify c->geometry or emit signals.
3835→ * Called by resize() for interactive resize and client_resize_do() for Lua-initiated resize.
3836→ */
3837→void
3838→apply_geometry_to_wlroots(Client *c)
3839→{
3840→	struct wlr_box clip;
3841→	int titlebar_left, titlebar_top;
3842→
3843→	if (!c->scene || !client_surface(c) || !client_surface(c)->mapped)
3844→		return;
3845→
3846→	/* Get titlebar sizes - they occupy space inside geometry */
3847→	titlebar_left = c->titlebar[CLIENT_TITLEBAR_LEFT].size;
3848→	titlebar_top = c->titlebar[CLIENT_TITLEBAR_TOP].size;
3849→
3850→	/* Update scene-graph position and borders */
3851→	wlr_scene_node_set_position(&c->scene->node, c->geometry.x, c->geometry.y);
3852→	/* Offset scene_surface by titlebar sizes (titlebars occupy space in geometry) */
3853→	wlr_scene_node_set_position(&c->scene_surface->node, c->bw + titlebar_left, c->bw + titlebar_top);
3854→	wlr_scene_rect_set_size(c->border[0], c->geometry.width, c->bw);
3855→	wlr_scene_rect_set_size(c->border[1], c->geometry.width, c->bw);
3856→	wlr_scene_rect_set_size(c->border[2], c->bw, c->geometry.height - 2 * c->bw);
3857→	wlr_scene_rect_set_size(c->border[3], c->bw, c->geometry.height - 2 * c->bw);
3858→	wlr_scene_node_set_position(&c->border[1]->node, 0, c->geometry.height - c->bw);
3859→	wlr_scene_node_set_position(&c->border[2]->node, 0, c->bw);
3860→	wlr_scene_node_set_position(&c->border[3]->node, c->geometry.width - c->bw, c->bw);
3861→
3862→	/* Update shadow geometry */
3863→	if (c->shadow.tree) {
3864→		const shadow_config_t *shadow_config = shadow_get_effective_config(
3865→			c->shadow_config, false);
3866→		shadow_update_geometry(&c->shadow, shadow_config,
3867→			c->geometry.width, c->geometry.height);
3868→	}
3869→
3870→	/* Update titlebar positions - they depend on current geometry */
3871→	client_update_titlebar_positions(c);
3872→
3873→	/* Request size change from client (subtract borders AND titlebars from geometry)
3874→	 * CRITICAL: Only send configure if there's no pending resize waiting for client commit.
3875→	 * Without this check, we flood the client with configure events on every refresh cycle,
3876→	 * which crashes Firefox and other clients that can't handle rapid configure floods. */
3877→	if (!c->resize) {
3878→		c->resize = client_set_size(c,
3879→				c->geometry.width - 2 * c->bw - titlebar_left - c->titlebar[CLIENT_TITLEBAR_RIGHT].size,
3880→				c->geometry.height - 2 * c->bw - titlebar_top - c->titlebar[CLIENT_TITLEBAR_BOTTOM].size);
3881→	}
3882→	client_get_clip(c, &clip);
3883→	wlr_scene_subsurface_tree_set_clip(&c->scene_surface->node, &clip);
3884→}
