200→ * Ported from AwesomeWM stack.c:stack_refresh (lines 162-199)
201→ * Applies computed stack order to wlroots scene graph
202→ */
203→void
204→stack_refresh(void)
205→{
206→	window_layer_t layer;
207→	Client *prev_in_layer[WINDOW_LAYER_COUNT];
208→	int scene_layer;
209→
210→	if (!need_stack_refresh)
211→		return;
212→
213→	/* Initialize previous pointers for each layer */
214→	for (layer = 0; layer < WINDOW_LAYER_COUNT; layer++) {
215→		prev_in_layer[layer] = NULL;
216→	}
217→
218→	/* Process stack from bottom to top, organizing by layer */
219→	foreach(node, globalconf.stack) {
220→		if (!(*node) || !(*node)->scene)
221→			continue;
222→
223→		layer = client_layer_translator(*node);
224→
225→		/* Skip IGNORE layer (transients are handled with their parents) */
226→		if (layer == WINDOW_LAYER_IGNORE)
227→			continue;
228→
229→		/* Move client to correct scene graph layer if needed */
230→		scene_layer = get_scene_layer(layer);
231→		/* Check if client is in wrong layer - skip the check if already correct
232→		 * to avoid unnecessary reparenting */
233→		if ((void *)(*node)->scene->node.parent != (void *)layers[scene_layer]) {
234→			wlr_scene_node_reparent(&(*node)->scene->node, layers[scene_layer]);
235→		}
236→
237→		/* Stack client and its transients */
238→		prev_in_layer[layer] = stack_transients_above(*node, prev_in_layer[layer]);
239→	}
240→
241→	/* Stack drawins (wiboxes) - AwesomeWM stacks these after clients
242→	 * Layer is determined by: ontop property AND type property (AwesomeWM compat)
243→	 * - type="desktop" → LyrBg (below everything, like wallpaper)
244→	 * - type="dock" → LyrTop (above normal windows, like panels)
245→	 * - ontop=true → LyrOverlay (above everything except fullscreen)
246→	 * - otherwise → LyrTile (same as normal clients) */
247→	foreach(drawin, globalconf.drawins) {
248→		if (!(*drawin)->scene_tree)
249→			continue;
250→
251→		/* Determine layer based on type and ontop (AwesomeWM compatibility) */
252→		if ((*drawin)->type == WINDOW_TYPE_DESKTOP ||
253→		    (*drawin)->type == WINDOW_TYPE_SPLASH) {
254→			/* Desktop/splash type goes to background layer (below clients) */
255→			scene_layer = LyrBg;
256→		} else if ((*drawin)->ontop) {
257→			/* ontop drawins go to overlay layer */
258→			scene_layer = LyrOverlay;
259→		} else if ((*drawin)->type == WINDOW_TYPE_DOCK) {
260→			/* Dock type goes above normal windows */
261→			scene_layer = LyrTop;
262→		} else {
263→			/* Normal drawins go to wibox layer (above clients but below ontop) */
264→			scene_layer = LyrWibox;
265→		}
266→
267→		/* Reparent to correct layer if needed */
268→		if ((void *)(*drawin)->scene_tree->node.parent != (void *)layers[scene_layer]) {
269→			wlr_scene_node_reparent(&(*drawin)->scene_tree->node, layers[scene_layer]);
270→		}
271→
272→		/* Raise to top of its layer (drawins stack above clients in same layer) */
273→		wlr_scene_node_raise_to_top(&(*drawin)->scene_tree->node);
274→	}
275→
276→	/* TODO: Call ewmh_update_net_client_list_stacking() */
277→
278→	need_stack_refresh = false;
279→}
